from pathlib import Path
import hashlib,json,re

ROOT=Path(__file__).resolve().parents[2]
MOD='书籍库/现代著作/当代壬占汇选第五版.md'
ANC='书籍库/现代著作/《壬占汇选》.txt'
REG='knowledge/liuren-research/20261102'

def text(path):return (ROOT/path).read_bytes().decode('utf-8-sig').splitlines()
def ref(path,a,b,role='原书断语',author='原载署名见完整案文'):
    raw=(ROOT/path).read_bytes()
    if role not in {'原书断语','原载反馈','原载作答','后人注解','旧AI归纳','本轮解释'}:
        author+='；段落身份细分：'+role
        role='原载作答' if path==MOD else '原书断语'
    return dict(path=path,line_start=a,line_end=b,quote='\n'.join(raw.decode('utf-8-sig').splitlines()[a-1:b]),sha256=hashlib.sha256(raw).hexdigest(),role=role,author=author)
def identity(path,a,b):return f'book:{path}:L{a}-L{b}'
def dump(path,value):
    p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True)
    tmp=p.with_suffix(p.suffix+'.b2tmp');tmp.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');tmp.replace(p)
def case(code,n,title,path,a,b,category,authors,question,boundary,feedback,methods,missing,notes,complete='complete',chart=None,extra=None):
    original_category=category
    category={'疾病占':'健康占','考试占':'学业占','文书占':'事业占','寻人寻物占':'失物占','寻人占':'失物占','风水占':'家宅占','谋事占':'事业占','行人占':'出行占','婚姻占':'感情占'}.get(category,category)
    sources=[ref(path,a,b)]+(extra or [])
    for dependency in sources[1:]:
        if '仅依' in dependency.get('author','') and '同前' in dependency.get('author',''):
            dependency['dependency_type']='borrowed_chart'
            dependency['same_event']=False
    all_text='\n'.join(r['quote'] for r in sources)
    exact_chart={k:v for k,v in (chart or {}).items() if v in all_text}
    chart_notes=[f'本轮串接原载字段（非逐字连续摘录、不重新推盘）：{k}={v}' for k,v in (chart or {}).items() if v not in all_text]
    return dict(schema='liuren-book-case-v1',id=f'BK26-{code}-{n:03}',title=title,book_title='当代壬占汇选第五版' if code=='MODERN' else '壬占汇选',category=category,subcategories=[original_category] if category!=original_category else [],source_case_identity=identity(path,a,b),review_state='source_checked',completeness=complete,boundary_note=boundary,question='本轮忠实概括：'+question,authors=authors,source_refs=sources,missing_fields=missing,feedback_status=feedback,method_rule_ids=methods,same_event_ids=[],notes=notes+chart_notes,chart_fields=exact_chart,chart_status='保留原载文本盘式；chart_fields仅逐字定位字段；未重新计算、未校原图',method_development_exposed=True,independent_validation_count=0)

