def rule(code,n,title,case_record,origin,conditions,conclusion,steps,alternatives,exclusions,refs,authors,limitations):
    return dict(schema='liuren-rule-card-v1',id=f'LR26-BOOK-{code}-{n:03}',title=title,categories=[case_record['category']],claim_origin=origin,review_state='source_checked',status='source_method' if origin=='原文明示' else 'candidate',conditions=conditions,exclusions=exclusions,conclusion=conclusion,reasoning_steps=steps,alternatives=alternatives,evidence_refs=refs,support_case_ids=[case_record['id'],case_record['source_case_identity']],source_case_ids=[case_record['id'],case_record['source_case_identity']],counterexample_case_ids=[],legacy_entry_ids=[],relations=[],limitations=limitations,independent_validation_count=0,reference_value='保留'+authors+'原载取用和推理；原载结果覆盖与事实核验另列，不因反馈未明否定方法价值。',method_development_exposed=True)

