def candidate_lists():
    # 只做边界候选扫描；不能据标题、盘式命中标成已精读。
    a=text(MOD);chapter='';marks=[]
    for n,line in enumerate(a,1):
        if line.startswith('# '):chapter=line;marks.append((n,'chapter',line,chapter))
        elif line.startswith('## '):marks.append((n,'section',line,chapter))
        elif re.fullmatch(r'[^#<>]{1,100}\s[｜|]\s占[^\s]{1,8}',line.strip()):marks.append((n,'section',line.strip(),chapter))
    mod=[]
    for idx,(n,kind,line,ch) in enumerate(marks):
        if kind=='section' and (ch.startswith('# 第二章') or ch.startswith('# 第三章')):
            end=marks[idx+1][0]-1 if idx+1<len(marks) else len(a)
            mod.append(dict(candidate_id=f'MOD-CAND-L{n}',path=MOD,line_start=n,line_end=end,title=line[3:] if line.startswith('## ') else line,chapter=ch,state='pending',completeness='pending',selection_method='章节内二级标题及显式无级别占类题头候选；未据此确认独立案例数或完整性'))
    a=text(ANC);nonempty=[(i,s) for i,s in enumerate(a,1) if s.strip()]
    starts=[]
    chart_letters=set('勾六合朱雀蛇螣腾贵后阴玄常虎空青龙白太天阴阳 ')
    for idx,(n,s) in enumerate(nonempty[:-1]):
        nxt=nonempty[idx+1][1].strip()
        if '占' not in s or any(k in s for k in ['曰','愚按','断：','断曰','何以','凡占','如占']):continue
        if len(s)>180:continue
        chart_line=bool(nxt) and all(x in chart_letters for x in nxt)
        same_before=nxt.startswith(('课式同前','同前课','课同前'))
        if chart_line or same_before:starts.append((n,s.strip(),same_before))
    anc=[]
    for idx,(n,title,same) in enumerate(starts):
        end=starts[idx+1][0]-1 if idx+1<len(starts) else len(a)
        anc.append(dict(candidate_id=f'ANC-CAND-L{n}',path=ANC,line_start=n,line_end=end,title=title,state='pending',completeness='pending',same_before_flag=same,selection_method='题头+后接盘式/同前的启发式候选；可能漏检/过宽，需逐段核边界'))
    return mod,anc

